# ===== 27 priority map =====
IMP = [("ضريبة وامتثال ورقابة خارجية", r"ضريب|ETA|هيئة|EDA|امتثال|قانون|تنظيم|مراجع خارجي|نموذج 41"),
       ("مخزون ودواء وتشغيلة", r"مخزون|تشغيلة|دفعة دواء|صلاحية|انتهاء|استدعاء|كمية|رصيد مخزن|مخزن"),
       ("سلامة البيانات والدفاتر", r"سلامة|تكرار|مكرر|ازدواج|قيد|دفتر|ميزان|GL|تسوية|انحراف|فقد"),
       ("مال وإيراد وذمم", r"إيراد|ذمم|مال|نقد|خزينة|تحصيل|سداد|دفع|خصم|سعر|أسعار|ربح|عمولة|حافز|راتب|رواتب|مدفوع|خسارة"),
       ("استمرارية التشغيل", r"يوقف|توقف|تعطل|نشر|تشغيل|متاح|استعادة|نسخ"),
       ("الرقابة والصلاحيات وفصل المهام", r"صلاحي|اعتماد|موافقة|فصل|احتيال|تلاعب|رقاب"),
       ("الكفاءة والتقارير", r".")]
def imp(r):
    t = (r.get('priority_reason') or '') + ' ' + (r.get('impact_ar') or '')
    for n, p in IMP:
        if re.search(p, t): return n
gap = lambda r: st(r['status_current']) in ('NOT_IMPLEMENTED','PARTIAL','CONTRADICTED','NOT_VERIFIED')
p = ["# 27 — خريطة الأولويات مربوطة بالأثر التجاري", "",
"**طريقة الأولوية:** P1 = يمس المال أو المخزون الدوائي أو الضريبة/الامتثال أو سلامة البيانات أو يوقف التشغيل اليومي · P2 = ضعف رقابي له بديل يدوي · P3 = كفاءة وتقارير · P4 = تحسين. فئة الأثر تُشتق آليًا من نص «الأثر» و«سبب الأولوية» لكل متطلب (أول فئة مطابقة بالترتيب أعلاه) ويُراجع عند الاعتماد. العدّ على المتطلبات الصافية التي **لم تكتمل في CURRENT**.", "",
"## 1. الأثر × الأولوية (فجوات CURRENT)", "", "| فئة الأثر | P1 | P2 | P3 | P4 | المجموع |", "|---|---|---|---|---|---|"]
cc = collections.Counter((imp(r), r['priority']) for r in net if gap(r))
for n, _ in IMP:
    p.append(f"| {n} | " + " | ".join(str(cc[(n, q)]) for q in ['P1','P2','P3','P4']) + f" | {sum(cc[(n,q)] for q in ['P1','P2','P3','P4'])} |")
p += ["", "## 2. العملية × الأولوية (فجوات CURRENT / المجموع)", "", "| العملية | P1 | P2 | P3 | P4 | قرارات مانعة |", "|---|---|---|---|---|---|"]
for b in ORDER:
    rs = [r for r in net if r['bucket']==b]
    p.append(f"| {BNAME[b]} | " + " | ".join(f"{sum(1 for r in rs if r['priority']==q and gap(r))} / {sum(1 for r in rs if r['priority']==q)}" for q in ['P1','P2','P3','P4']) + f" | {sum(1 for d in decs if d['bucket']==b and d.get('blocking'))} |")
p += ["", "## 3. موجات مقترحة للمناقشة (ليست خطة تنفيذ)", "",
"الترتيب يتبع منطق الاعتماد لا الأهمية وحدها: لا يُعتمد متطلب يعتمد على قرار مفتوح قبل حسمه.", "",
"| الموجة | المحتوى | شرط البدء |", "|---|---|---|",
"| 0 — الحقيقة التشغيلية | أدلة E-01…E-07 (أي كود وأي schema يعمل، النسخ الاحتياطي) | لا شيء؛ أوامر قراءة فقط |",
"| 1 — القرارات المانعة | 75 قرارًا مانعًا + 9 تعارضات عابرة (`25` §1–2) | جلسات مالك قصيرة بالمجموعات في `28` |",
"| 2 — P1 مال/مخزون/ضريبة/سلامة بيانات | المتطلبات P1 غير المكتملة في الفئات الأربع الأولى (القائمة §4) | حسم قراراتها + الموجة 0 |",
"| 3 — P1 تشغيل ورقابة + P2 | فصل المهام، الموافقات، العكس والإلغاء | بعد اعتماد مصفوفة SoD (`28`، C8) |",
"| 4 — P3/P4 | تقارير وكفاءة وتحسينات | بعد نموذج التقارير (DAR-13) |", "",
"## 4. قائمة P1 غير المكتملة مرتبة بفئة الأثر", ""]
for n, _ in IMP:
    rs = sorted([r for r in net if r['priority']=='P1' and gap(r) and imp(r)==n], key=lambda r: (ORDER.index(r['bucket']), r['req_id']))
    if not rs: continue
    p += [f"### {n} ({len(rs)})", "", "| ID | المتطلب | C | الأثر | قرارات | DAR |", "|---|---|---|---|---|---|"]
    for r in rs:
        p.append(f"| {r['req_id']} | {short(r['title_ar'],90)} | {STAT_AR[st(r['status_current'])]} | {short(r['impact_ar'],120)} | {', '.join(r['decision_refs'][:3])} | {', '.join(r['dar'][:4])} |")
    p.append("")
open(f'{OUT}/27-Priority-Map.md', 'w').write('\n'.join(p))
